// ─── File: PaymentWorkflowDemo.java ───
// Runnable demo. In a real project each class lives in its own file under the
// packages shown in the structure above. Here they are top-level package-private
// classes in one file so the demo compiles and runs as-is.

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.*;

public class PaymentWorkflowDemo {

    private static final Logger log = Logger.getLogger("payment");

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository accounts = new AccountRepository();
        PaymentRepository payments = new PaymentRepository();

        PaymentInitiationService initiation = new PaymentInitiationService(accounts, payments);
        SettlementConsumer settlement = new SettlementConsumer(payments);
        AuditReconstructor audit = new AuditReconstructor(payments);

        // STEP 1: Rajesh initiates a transfer. A durable paymentId is minted here.
        String paymentId = initiation.initiate("SAV2001", "BENEF-GB-9981",
                new BigDecimal("200000"));

        // STEP 2: Two days later a Kafka message is consumed. A NEW technical trace
        // would start here, but the SAME paymentId continues the business story.
        settlement.onPaymentInitiated(new PaymentInitiatedEvent(paymentId,
                /* traceId from producer, may already be purged */ "trace-OLD-expired"));

        // STEP 3: A month later the customer disputes. The trace is long gone, but we
        // reconstruct the full operation purely from the durable paymentId.
        audit.reconstruct(paymentId);
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId;
    final String holderName;
    BigDecimal balance;
    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("insufficient funds");
        balance = balance.subtract(amount);
    }
    void credit(BigDecimal amount) { balance = balance.add(amount); }
}

// ─── Would be in model/Payment.java ───
class Payment {
    final String paymentId;         // durable business identifier
    final String fromAccount;
    final String beneficiary;
    final BigDecimal amount;
    String status;                  // INITIATED, SETTLED, FAILED
    String lastTraceId;             // best-effort technical trace (may expire)
    final LocalDateTime createdAt = LocalDateTime.now();
    LocalDateTime settledAt;
    Payment(String paymentId, String fromAccount, String beneficiary, BigDecimal amount) {
        this.paymentId = paymentId; this.fromAccount = fromAccount;
        this.beneficiary = beneficiary; this.amount = amount; this.status = "INITIATED";
    }
}

// ─── Would be in event/PaymentInitiatedEvent.java ───
class PaymentInitiatedEvent {
    final String paymentId;   // business id — survives forever, travels in the event body
    final String traceId;     // technical id — convenience only, may be purged
    PaymentInitiatedEvent(String paymentId, String traceId) {
        this.paymentId = paymentId; this.traceId = traceId;
    }
}

// ─── Would be in repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
}

// ─── Would be in repository/PaymentRepository.java ───
class PaymentRepository {
    private final Map<String, Payment> store = new LinkedHashMap<>();
    void save(Payment p) { store.put(p.paymentId, p); }
    Payment findById(String id) { return store.get(id); }
}

// ─── Would be in service/PaymentInitiationService.java ───
class PaymentInitiationService {
    private static final Logger log = Logger.getLogger("payment");
    private final AccountRepository accounts;
    private final PaymentRepository payments;
    PaymentInitiationService(AccountRepository a, PaymentRepository p) { accounts = a; payments = p; }

    String initiate(String fromId, String beneficiary, BigDecimal amount) {
        // Mint the durable business identifier ONCE, at birth of the operation.
        String paymentId = "PAY-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        String traceId = currentTraceId();   // short-lived technical id

        Account from = accounts.findById(fromId);
        from.debit(amount);

        Payment p = new Payment(paymentId, fromId, beneficiary, amount);
        p.lastTraceId = traceId;
        payments.save(p);

        log.info(() -> "paymentId=" + paymentId + " traceId=" + traceId
                + " INITIATED debit Rs." + amount + " from " + fromId);

        // Publish event carrying the durable paymentId (and trace for convenience).
        publish(new PaymentInitiatedEvent(paymentId, traceId));
        return paymentId;
    }

    private void publish(PaymentInitiatedEvent e) {
        log.fine(() -> "published PaymentInitiatedEvent paymentId=" + e.paymentId);
    }
    private String currentTraceId() { return "trace-" + UUID.randomUUID().toString().substring(0, 6); }
}

// ─── Would be in service/SettlementConsumer.java ───
class SettlementConsumer {
    private static final Logger log = Logger.getLogger("payment");
    private final PaymentRepository payments;
    SettlementConsumer(PaymentRepository p) { payments = p; }

    // Consumed hours/days later. A brand-new technical trace begins here.
    void onPaymentInitiated(PaymentInitiatedEvent event) {
        String newTraceId = "trace-" + UUID.randomUUID().toString().substring(0, 6);
        Payment p = payments.findById(event.paymentId);   // joined ONLY by durable business id
        p.status = "SETTLED";
        p.settledAt = LocalDateTime.now();
        p.lastTraceId = newTraceId;
        payments.save(p);
        log.info(() -> "paymentId=" + p.paymentId + " traceId=" + newTraceId
                + " SETTLED (producer trace " + event.traceId + " already expired)");
    }
}

// ─── Would be in service/AuditReconstructor.java ───
class AuditReconstructor {
    private static final Logger log = Logger.getLogger("payment");
    private final PaymentRepository payments;
    AuditReconstructor(PaymentRepository p) { payments = p; }

    void reconstruct(String paymentId) {
        Payment p = payments.findById(paymentId);
        log.info(() -> "RECONSTRUCT paymentId=" + p.paymentId
                + " status=" + p.status
                + " from=" + p.fromAccount + " beneficiary=" + p.beneficiary
                + " amount=Rs." + p.amount
                + " created=" + p.createdAt + " settled=" + p.settledAt
                + "  (reconstructed from durable business id, no live trace needed)");
    }
}

// ─── Would be in config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tH:%1$tM:%1$tS %2$-7s %3$s%n",
                new Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
